INSERT INTO `tb_products` VALUES (5,'AMZ-ECHOSHOW21-2024-BLK','Amazon Echo Show 21','Pantalla inteligente Amazon Echo Show 21 de 21.4 pulgadas Full HD 1920x1080, Alexa integrada, Fire TV, cámara de 13 MP, Wi-Fi 6E, Bluetooth 5.0, 4 GB de RAM, almacenamiento interno de 16 GB, sistema de audio con dos woofers de 2 pulgadas y dos tweeters de 0.6 pulgadas. Incluye control remoto por voz Alexa y soporte para montaje en pared. Color negro.',7999.00,12,_binary '','2026-09-22 10:28:19','2026-09-22 10:28:19'),(6,'OAK-OO9415-0142','Oakley Corridor SQ OO9415 Sunglasses Men','Lentes de sol Oakley Corridor SQ modelo OO9415-0142 para hombre, tamaño XL 138 mm, armazón Matte Black fabricado en O Matter, diseño semicontorneado rectangular, micas Prizm Black con transmisión de luz del 11%, almohadilla nasal y patillas de Unobtainium para mayor agarre y tecnología Prizm para mejorar color y contraste.',5059.00,18,_binary '','2026-09-22 10:28:19','2026-09-22 10:28:19'),(7,'PROD-001','Laptop Dell XPS 13','Laptop ultraligera con procesador Intel i7 y 16GB RAM',24999.00,10,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(8,'PROD-002','Smartphone Samsung S23','Teléfono móvil con cámara de 50MP y pantalla AMOLED',18500.50,15,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(9,'PROD-003','Audífonos Sony WH-1000XM5','Audífonos inalámbricos con cancelación de ruido activa',6800.00,25,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(10,'PROD-004','Monitor LG 27 Pulgadas','Monitor Gaming 4K IPS de 144Hz',7499.99,8,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(11,'PROD-005','Teclado Mecánico Logitech','Teclado RGB con switches táctiles inalámbrico',2200.00,30,_binary '','2026-09-22 10:48:20','2026-09-22 10:48:20'),(12,'RAM-00001-988','NexaMemory Memoria RAM DDR4 8GB 2666MHz 1 módulo RAM0001','Memoria de escritorio DDR4, capacidad total 8 GB, frecuencia 2666 MHz, formato UDIMM, 1 módulo. Marca comercial simulada NexaMemory. Modelo interno RAM0001.',1490.51,