/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN

    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_date,
        operation_description,
        operation_status
    )
    VALUES (
        'tb_products',
        'Update',
        USER(),
        CURRENT_TIMESTAMP,

        CONCAT(
            'Producto actualizado. ID=', NEW.ID,
            ', Cambios: ',

            CONCAT_WS(
                ' | ',

                IF(
                    NOT (OLD.SKU <=> NEW.SKU),
                    CONCAT(
                        'SKU: ',
                        OLD.SKU,
                        ' -> ',
                        NEW.SKU
                    ),
                    NULL
                ),

                IF(
                    NOT (OLD.name <=> NEW.name),
                    CONCAT(
                        'Nombre: ',
                        OLD.name,
                        ' -> ',
                        NEW.name
                    ),
                    NULL
                ),

                IF(
                    NOT (OLD.description <=> NEW.description),
                    'Descripción modificada',
                    NULL
                ),

                IF(
                    NOT (OLD.current_price <=> NEW.current_price),
                    CONCAT(
                        'Precio: ',
                        OLD.current_price,
                        ' -> ',
                        NEW.current_price
                    ),
                    NULL
                ),

                IF(
                    NOT (OLD.current_stock <=> NEW.current_stock),
                    CONCAT(
                        'Stock: ',
                        OLD.current_stock,
                        ' -> ',
                        NEW.current_stock
                    ),
                    NULL
                ),

                IF(
                    NOT (OLD.status <=> NEW.status),
