/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_categories_after_delete` AFTER DELETE ON `tbc_categories` FOR EACH ROW BEGIN

    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tbc_categories',
        'Delete',
        USER(),

        CONCAT(
            'Categoría eliminada. ',
            'ID=', OLD.ID,
            ', name=', OLD.name,
            ', description=', COALESCE(OLD.description, 'NULL'),
            ', sup_id_category=', COALESCE(OLD.sup_id_category, 'NULL'),
            ', status=', OLD.status + 0
        ),

        CURRENT_TIMESTAMP,
        b'1'
    );

END */;;
